1: name: "OWASP Dependency Check"
2: on:
3:   push:
4:     branches:
5:       - master
6:       - '2.*.x'
7: jobs:
8:   dependencycheck:
9:     runs-on: ubuntu-latest
10:     # a stalled NVD feed download otherwise runs until the 6 hour GitHub default; normal runs
11:     # take 3-8 minutes with occasional NVD-update tails up to ~35, so 60 clears the worst observed
12:     timeout-minutes: 60
13:     name: dependencycheck_test
14:     steps:
15:       - name: Checkout
16:         uses: actions/checkout@v7.0.1
17:       - name: Set up Java version
18:         uses: actions/setup-java@v6.0.0
19:         with:
20:           java-version: '21'
21:           distribution: 'temurin'
22:           cache: 'maven'
23:       - name: Build project with Maven
24:         run: mvn clean install -DskipTests
25:       - name: Run OWASP Dependency-Check
26:         uses: dependency-check/Dependency-Check_Action@main
27:         id: Depcheck
28:         env:
29:           JAVA_HOME: /opt/jdk
30:         with:
31:           project: 'openmrs-core'
32:           path: '.'
33:           format: 'ALL'
34:           out: 'reports'
35:           args: >
36:             --failOnCVSS 6.2
37:             --enableRetired
38:             --suppression dependency-check-suppressions.xml
39:             ${{ secrets.NVD_API_KEY != '' && format('--nvdApiKey {0}', secrets.NVD_API_KEY) || '' }}
40:       - name: Upload Test results
41:         if: always()
42:         uses: actions/upload-artifact@v7
43:         with:
44:            name: Dependency Check report
45:            path: ${{github.workspace}}/reports
